WITH filtered_store_sales AS (SELECT *, revenue * units AS revenue_per_unit FROM store_sales WHERE product_id = 3), Summary AS (SELECT QUARTER(sale_date) AS sale_quarter, MIN(sale_date) AS first_sale_date, ROUND(AVG(revenue_per_unit), 2) AS avg_revenue_per_unit FROM filtered_store_sales GROUP BY QUARTER(sale_date)) SELECT sale_quarter, first_sale_date, avg_revenue_per_unit FROM Summary ORDER BY first_sale_date;
